"""
wpp_signatures.py — single source of truth for PARTNER signatures across all
rendered documents (cover letter, CIR, note card, case study).

Mirrors the VTI_B64 embed pattern (base64 constant -> data URI) so no container
asset path / fontconfig dependency. Assets are pre-trimmed to the ink bounding box
and width-capped, so callers just set a print height in CSS and the mark lands
consistently on every document.

Usage in an engine:
    from wpp_signatures import signature_data_uri
    ctx["signature_uri"] = signature_data_uri()          # default = "3"
    # template:  <img src="{{ signature_uri }}" style="height:64px" alt="">

Default is "3" (contained mark, cleaner at print scale). Pass which="2" for the
long-sweep variant on formal / full-page documents.
"""

# John Wylie — contained variant (DEFAULT). Ink ~#16317E, transparent, pre-trimmed.
SIGNATURE_JW_3_B64 = ""

# John Wylie — long-sweep variant.
SIGNATURE_JW_2_B64 = ""

# --- Arvo Kaseorg (partner 1) -----------------------------------------------
# Set 2026-08-27. A typeset script mark (Alex Brush), not a scan of a written
# signature: rendered to the same spec as John's — #16317E ink, transparent,
# trimmed to the ink bounding box, 640px wide.
#
# WIDTH. John's mark is a compact scrawl, 640x472 (0.74 aspect), and the locked
# template prints it at width:115px. A written-out name is inherently wide and
# short — this one is 640x116 — so at 115px it would print 21px tall and read as
# markedly slighter than John's on the same page. 165px gives it comparable
# presence. That is why width is a property of the signature, not a constant in
# the template CSS.
SIGNATURE_AK_1_B64 = ""

_SIGS = {"3": SIGNATURE_JW_3_B64, "2": SIGNATURE_JW_2_B64, "ak1": SIGNATURE_AK_1_B64}
SIGNATURE_JW_DEFAULT = "3"

# Printed width in the cover letter, per signature. Anything not listed prints at
# the template default.
SIGNATURE_WIDTH_PX = {"3": 115, "2": 115, "ak1": 165}
SIGNATURE_WIDTH_DEFAULT = 115

# partner_signature.partner_id -> signature key. THE mapping; nothing else may
# decide whose mark goes on a document.
#   1 Arvo Kaseorg  2 Reggie Bowers (no mark yet)  3 John Wylie
PARTNER_SIGNATURE = {1: "ak1", 3: "3"}


def signature_b64(which: str = SIGNATURE_JW_DEFAULT) -> str:
    """Raw base64 for the requested signature variant ('3' default, or '2')."""
    return _SIGS.get(str(which), _SIGS[SIGNATURE_JW_DEFAULT])


def signature_width_px(which: str = SIGNATURE_JW_DEFAULT) -> int:
    """Printed width in px for this mark in the cover letter."""
    return SIGNATURE_WIDTH_PX.get(str(which), SIGNATURE_WIDTH_DEFAULT)


class UnknownSignature(KeyError):
    """No mark registered. Never resolved by falling back to someone else's."""


def signature_for_partner(partner_id) -> str:
    """The signature KEY for a partner. Raises rather than substituting.

    signature_b64() falls back to John's mark on an unknown key, which is right
    for a legacy '3'/'2' variant string and catastrophic for a partner: it would
    print John's signature under Arvo's typed name. Partner lookups come through
    here, and a partner with no registered mark stops the render.
    """
    try:
        key = PARTNER_SIGNATURE[int(partner_id)]
    except (KeyError, TypeError, ValueError):
        raise UnknownSignature(
            f"no signature registered for partner_id={partner_id!r}; "
            f"refusing to sign with another partner's mark")
    if key not in _SIGS:
        raise UnknownSignature(f"signature key {key!r} for partner_id={partner_id!r} is not in _SIGS")
    return key


def signature_data_uri(which: str = SIGNATURE_JW_DEFAULT) -> str:
    """Ready-to-embed PNG data URI for <img src=...>."""
    return "data:image/png;base64," + signature_b64(which)
